const clamp=(x,a,b)=>Math.max(a,Math.min(b,x)),ns='http://www.w3.org/2000/svg';
export function eqBands(id){if(id==='vectoreq')return Array.from({length:6},(_,i)=>({f:'f'+i,g:'g'+i,q:'q'+i,type:'peaking'}));if(id==='circuiteq')return ['low','body','presence','air'].map((g,i)=>({f:['lowFreq','bodyFreq','presenceFreq','airFreq'][i],g,type:i===0?'lowshelf':i===3?'highshelf':'peaking',proportional:true}));if(id==='prism')return ['low','mid','high'].map((g,i)=>({f:g+'Freq',g,q:i===1?'q':null,type:i===0?'lowshelf':i===2?'highshelf':'peaking'}));return null;}
let responseContext;
export function mountEqCurve({root,id,state,definition,checkpoint,change,master=false}){const bands=eqBands(id);if(!bands)return;responseContext??=new OfflineAudioContext(1,128,48000);const filters=bands.map(b=>{const f=responseContext.createBiquadFilter();f.type=b.type;return f;}),section=document.createElement('section');section.className='eq-curve-editor';section.innerHTML='<div><strong>ÉGALISATION · COURBE DIRECTE</strong><span>Glisse : Hz / dB · molette : Q · double-clic : réinitialiser</span></div><svg viewBox="0 0 640 220" preserveAspectRatio="none" tabindex="0" aria-label="Courbe EQ interactive"></svg><output></output>';const target=root.querySelector(master?'.master-module-params':'.plugin-window-params');target.before(section);const svg=section.querySelector('svg'),status=section.querySelector('output'),frequencies=Float32Array.from({length:240},(_,i)=>20*1000**(i/239)),magnitudes=new Float32Array(240),phases=new Float32Array(240);let selected=0,drag=null;
 const x=f=>Math.log(f/20)/Math.log(1000)*640,y=g=>110-g/24*100,element=(tag,attrs)=>{const el=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))el.setAttribute(k,v);return el;};
 function paint(){svg.replaceChildren();for(const freq of [50,100,500,1000,5000,10000]){svg.append(element('path',{d:`M${x(freq)} 0V220`,class:'eq-grid'}));const label=element('text',{x:x(freq)+3,y:16});label.textContent=freq>=1000?freq/1000+'k':freq;svg.append(label);}for(const gain of [-18,-12,-6,0,6,12,18])svg.append(element('path',{d:`M0 ${y(gain)}H640`,class:gain===0?'eq-zero':'eq-grid'}));const total=new Float64Array(240);bands.forEach((b,i)=>{const f=filters[i];f.frequency.value=state[b.f];f.gain.value=state[b.g];f.Q.value=b.proportional?.5+Math.abs(state[b.g])/5:b.q?state[b.q]:.8;f.getFrequencyResponse(frequencies,magnitudes,phases);for(let j=0;j<240;j++)total[j]+=20*Math.log10(Math.max(1e-6,magnitudes[j]));});svg.append(element('polyline',{points:[...frequencies].map((f,i)=>`${x(f)},${clamp(y(total[i]),1,219)}`).join(' '),class:'eq-response'}));bands.forEach((b,i)=>{svg.append(element('circle',{cx:x(state[b.f]),cy:y(state[b.g]),r:i===selected?8:6,'data-eq-band':i,tabindex:0,role:'slider','aria-label':'Bande '+(i+1)+' fréquence et gain','aria-valuetext':Math.round(state[b.f])+' Hz, '+state[b.g].toFixed(1)+' dB',class:i===selected?'selected':''}));});const b=bands[selected];status.textContent=`B${selected+1} · ${Math.round(state[b.f])} Hz · ${state[b.g].toFixed(2)} dB${b.q?' · Q '+state[b.q].toFixed(1):''}`;}
 function update(key,value){const c=definition.controls.find(c=>c.key===key);if(!c)return;state[key]=clamp(value,c.min,c.max);change(key,state[key]);}
 svg.onpointerdown=e=>{const point=e.target.closest('[data-eq-band]');if(e.button!==0||!point)return;selected=Number(point.dataset.eqBand);checkpoint();drag={x:e.clientX,y:e.clientY,f:state[bands[selected].f],g:state[bands[selected].g]};svg.setPointerCapture(e.pointerId);paint();e.preventDefault();};svg.onpointermove=e=>{if(!drag)return;const b=bands[selected],r=svg.getBoundingClientRect();update(b.f,e.shiftKey?drag.f*1000**((e.clientX-drag.x)/r.width*.1):20*1000**clamp((e.clientX-r.left)/r.width,0,1));update(b.g,e.shiftKey?drag.g-(e.clientY-drag.y)/r.height*48*.1:(.5-(e.clientY-r.top)/r.height)*48);paint();};svg.onpointerup=()=>drag=null;svg.onpointercancel=()=>drag=null;
 svg.onwheel=e=>{const point=e.target.closest('[data-eq-band]');if(!point)return;selected=Number(point.dataset.eqBand);const b=bands[selected];if(!b.q)return;e.preventDefault();checkpoint();update(b.q,state[b.q]+(e.deltaY<0?.1:-.1));paint();};svg.ondblclick=e=>{const point=e.target.closest('[data-eq-band]');if(!point)return;selected=Number(point.dataset.eqBand);checkpoint();for(const key of [bands[selected].f,bands[selected].g,bands[selected].q].filter(Boolean))update(key,definition.controls.find(c=>c.key===key).default);paint();};svg.onkeydown=e=>{const point=e.target.closest('[data-eq-band]');if(point)selected=Number(point.dataset.eqBand);if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();checkpoint();const b=bands[selected];if(e.key==='ArrowLeft'||e.key==='ArrowRight')update(b.f,state[b.f]*2**((e.key==='ArrowRight'?1:-1)/12));else update(b.g,state[b.g]+(e.key==='ArrowUp'?1:-1)*(e.shiftKey?.1:.5));paint();};paint();return {redraw:paint};
}
